M_{ab}\: & = \:\triangle R_{ab}-\frac12\nabla_a\nabla_bR
+2R_{acbd}R_{cd}-R_{ac}R_{bc}+\frac{R_{ab}}{2t}. \notag
\end{align}
For a $2$-form $U$ and a $1$-form $W$, set
\begin{equation}
Z(U,W)\:=\:M_{ab}W_aW_b+2P_{abc}U_{ab}W_c+R_{abcd}U_{ab}U_{cd}.
\end{equation}
